-- SQLite schema for regional dictionary contributions.
-- Run this once before importing INSERT statements generated by language-data.html.
CREATE TABLE IF NOT EXISTS language_words (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    language_code TEXT NOT NULL CHECK (language_code IN ('tj-TJ', 'bq-BQ', 'ky-KY', 'bh-BH', 'kt-KT')),
    language_name TEXT NOT NULL,
    word TEXT NOT NULL CHECK (length(trim(word)) > 0),
    translation TEXT NOT NULL CHECK (length(trim(translation)) > 0),
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (language_code, word)
);

CREATE INDEX IF NOT EXISTS idx_language_words_translation
    ON language_words (translation COLLATE NOCASE);
